package example;

import example.dto.BookView;
import java.math.BigDecimal;
import org.babyfish.jimmer.Page;
import org.babyfish.jimmer.sql.JSqlClient;
import org.babyfish.jimmer.sql.ast.mutation.SaveMode;

public final class CanaryJava {

    private CanaryJava() {}

    public static BookView create(
            JSqlClient sql,
            String name,
            BigDecimal price,
            String tenant
    ) {
        Book input = BookDraft.$.produce(draft -> {
            draft.setName(name);
            draft.setPrice(price);
            draft.setTenantId(tenant);
            draft.setVersion(0);
        });

        return sql.saveCommand(input)
                .setMode(SaveMode.INSERT_ONLY)
                .execute(BookView.class)
                .getModifiedView();
    }

    public static Page<BookView> search(
            JSqlClient sql,
            String name,
            int page,
            int size
    ) {
        BookTable book = BookTable.$;

        return sql.createQuery(book)
                .where(book.name().likeIf(name))
                .orderBy(book.name().asc(), book.id().asc())
                .select(book.fetch(BookView.class))
                .fetchPage(page, size);
    }
}
```

**No, `isAccepted()` is not available in official Jimmer 0.9.111.** `INSERT_ONLY` strictly inserts; duplicate-key failures propagate because this method does not catch them. The generated identity ID is left unset.

`execute(BookView.class).getModifiedView()` requests the required successful-save shape directly, potentially using a follow-up fetch, rather than converting a possibly partially loaded entity.

`likeIf(name)` skips an absent name filter. Pagination uses a zero-based page index and stable ordering by name, then ID.
